import{_ as e}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as r,a as s,b as o,c as t,d as i,e as n}from"./chunks/3DM-BR-CB7.Bp-b42-4.js";import{_ as l}from"./chunks/BDM.scaBLLhv.js";import{_ as d}from"./chunks/DIS.DdpTdGGD.js";import{_ as u,o as p,c,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const R=JSON.parse('{"title":"Réinstallation","description":"","frontmatter":{"source_hash":"59290c3e55","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/troubleshoot/reinstall.md","filePath":"fr/troubleshoot/reinstall.md"}'),v={name:"fr/troubleshoot/reinstall.md"};function b(h,a,g,f,x,z){return p(),c("div",null,[...a[0]||(a[0]=[m('<h2 id="uninstall-xdrip" tabindex="-1">Désinstaller xDrip <a class="header-anchor" href="#uninstall-xdrip" aria-label="Permalink to &quot;Désinstaller xDrip {#uninstall-xdrip}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Données historiques</p><p>Désinstaller xDrip supprime aussi toutes les données et tous les paramètres, sans récupération possible.<br> Veillez à <strong><a href="#backup">sauvegarder</a></strong> la base de données et/ou tous les paramètres au préalable.<br> Il est recommandé d&#39;envoyer les données vers <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>.</p></div><br><p>Cela ne devrait normalement pas être nécessaire, mais vous pouvez avoir besoin de désinstaller xDrip pour un dépannage, ou pour passer à une version dérivée (fork) ou en revenir. Vous pouvez désinstaller xDrip comme n&#39;importe quelle autre application Android, par un appui long sur l&#39;icône ou depuis Paramètres Android -&gt; Applications.</p><h2 id="reinstall-xdrip" tabindex="-1">Réinstaller xDrip <a class="header-anchor" href="#reinstall-xdrip" aria-label="Permalink to &quot;Réinstaller xDrip {#reinstall-xdrip}&quot;">​</a></h2><p>Suivez cette séquence :</p><ol><li>Sauvegardez (localement ou dans le cloud)</li><li>Désinstallez xDrip</li><li>Installez xDrip</li><li>Restaurez (depuis la sauvegarde locale ou dans le cloud)</li><li>Vérifiez tous vos paramètres et recréez vos alarmes</li></ol><h2 id="backup" tabindex="-1">Sauvegarde <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Sauvegarde {#backup}&quot;">​</a></h2><p>Vous pouvez sauvegarder la base de données localement ou dans votre <a href="#cloud-backup">Google Drive</a>.</p><h3 id="backup-the-database" tabindex="-1">Sauvegarder la base de données <a class="header-anchor" href="#backup-the-database" aria-label="Permalink to &quot;Sauvegarder la base de données {#backup-the-database}&quot;">​</a></h3><p>La base de données contient toutes les valeurs de glycémie, les traitements et les notes. Il est fortement recommandé de sauvegarder votre base de données et d&#39;en garder une copie sur un autre appareil si vous voulez conserver vos données existantes, et par précaution en cas de perte du téléphone, de panne...<br> L&#39;envoi vers <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> est aussi fortement recommandé.</p><p>L&#39;exportation de la base de données <a href="./../use/loadsavesettings.html#save-settings">enregistre aussi les paramètres</a>.</p><p>Depuis l&#39;écran principal de xDrip, sélectionnez le menu à 3 points en haut à droite, Fonctionnalités Import / Export, Exporter la base de données.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Fonctionnalités Import / Export ►<br>  Exporter la base de données</p></div><br><p>La base de données actuelle sera enregistrée dans <code>/storage/emulated/0/xdrip</code> ou <code>Internal Storage/xdrip</code> Vous devez autoriser xDrip à accéder à la mémoire de votre téléphone.<br> Vous pouvez faire autant de sauvegardes que votre mémoire peut en contenir.</p><p>Si vous êtes assez rapide pour appuyer sur <code>PARTAGER</code> avant qu&#39;il disparaisse, vous pouvez utiliser les options de partage de votre téléphone pour envoyer la base de données vers un autre appareil ou la copier à un autre emplacement.</p><img src="'+r+'" style="zoom:75%;"><p>Votre sauvegarde sera nommée <code>exportYYYYMMDD-HHMMSS.zip</code>, avec <code>YYYY</code> l&#39;année en cours, <code>MM</code> le mois, <code>DD</code> le jour et <code>HHMMSS</code> les heures, minutes et secondes. Vous pouvez ainsi avoir plusieurs sauvegardes identifiées par un horodatage unique.</p><p>Si vous voulez en garder une copie en lieu sûr, envoyez-vous le fichier par e-mail, enregistrez-le sur un stockage en ligne ou copiez-le par USB sur un ordinateur.</p><p>C&#39;est une base de données SQLite que vous pouvez parcourir avec divers utilitaires comme <a href="https://sqlitebrowser.org/" target="_blank" rel="noreferrer">SQLite Browser</a>.</p><br><h2 id="restore" tabindex="-1">Restauration <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restauration {#restore}&quot;">​</a></h2><p>Vous pouvez restaurer la base de données depuis une copie locale ou depuis votre <a href="#cloud-backup">Google Drive</a>.</p><h3 id="restore-settings" tabindex="-1">Restaurer les paramètres <a class="header-anchor" href="#restore-settings" aria-label="Permalink to &quot;Restaurer les paramètres {#restore-settings}&quot;">​</a></h3><p>Une fois l&#39;installation de xDrip terminée, si une sauvegarde est disponible, xDrip proposera de la restaurer automatiquement.<br> Sélectionnez RÉTABLIR LES PARAMÈTRES</p><div class="admonition xdripitem"><p class="admonition-title">Sauvegarde détectée</p><p> Il semble que vous ayez peut-être une sauvegarde des paramètres, devons-nous essayer de la restaurer?</p><p> NON    <span style="background-color:white;color:black;"> RÉTABLIR LES PARAMÈTRES </span></p></div><p>Si vous ne voyez pas ce message, <a href="./../use/loadsavesettings.html#load-settings">restaurez-les manuellement</a>.</p><h3 id="restore-a-database" tabindex="-1">Restaurer une base de données <a class="header-anchor" href="#restore-a-database" aria-label="Permalink to &quot;Restaurer une base de données {#restore-a-database}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Perte de données</p><p>Restaurer une base de données <strong>supprime toutes les données actuelles</strong>.<br> Restaurez une base de données avec <strong>la même version de xDrip que celle utilisée pour l&#39;exporter</strong>.<br> Veillez à sauvegarder la base de données actuelle avant d&#39;en restaurer une.</p></div><p>Une fois l&#39;installation de xDrip terminée, si une sauvegarde de base de données est disponible, xDrip peut proposer de la restaurer automatiquement.</p><p>Vérifiez qu&#39;il s&#39;agit bien de la base de données que vous voulez restaurer, puis sélectionnez RESTAURER.</p><div class="admonition xdripitem"><p class="admonition-title">Restaurer la sauvegarde ?</p><p> Voulez-vous restaurer le fichier de sauvegarde : export20210328-085436.zip</p><p> NON    <span style="background-color:white;color:black;"> RESTAURER </span></p></div><p>xDrip confirmera que la base de données a bien été restaurée.</p><div class="admonition xdripitem"><p class="admonition-title">Import Result</p><p> Successfully imported database</p></div><p><em>Remarque : par sécurité, la base de données actuelle est d&#39;abord exportée ; vous la trouverez dans la liste sous le nom <code>b4import</code> suivi de la date et de l&#39;heure de l&#39;importation. Vous pourrez ainsi la récupérer si nécessaire.</em></p><br><p>Si vous voulez restaurer une sauvegarde précise, depuis l&#39;écran principal de xDrip, sélectionnez le menu à 3 points en haut à droite, Fonctionnalités Import / Export, Importer la base de données.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Fonctionnalités Import / Export ►<br>  Importer la base de données</p></div><p>Des instructions s&#39;affichent. Vous n&#39;avez pas besoin de déplacer le fichier de sauvegarde si vous ne l&#39;avez pas apporté d&#39;un autre appareil, ni de le décompresser. Soyez prudent si vous restaurez une base de données avec une autre version de xDrip : il est recommandé d&#39;installer la <a href="./../install/install.html#verify-which-version-is-installed">version de xDrip</a> qui a servi à l&#39;exportation avant d&#39;importer, puis de mettre à jour xDrip ensuite.</p><div class="admonition xdripitem"><p class="admonition-title">Restore Instructions</p><p> WARNING: Database restore is rarely necessary and may cause SEVERE DATA LOSS.</p><p>Protect your data by uploading to Nightscout or Tidepool.</p><p>When switching phones, importing settings (alerts, colors, etc.) is usually sufficient. Restoring the database is typically unnecessary unless you need short-term access to historical data (for example, before a medical visit).</p><p>Instructions:</p><p>- Place the database in the &#39;xdrip&#39; folder. If it doesn&#39;t exist, perform an export once to create it.</p><p>- Restart this restore routine.</p><p>- Select the correct database and follow the on-screen instructions.</p></div><p>Sélectionnez la base de données à importer ; regardez la date et la taille (avec le gestionnaire de fichiers du téléphone) pour être sûr de choisir la bonne.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+l+'" style="zoom:75%;">Restaurer la base de données</p><p>export20220129-184625.zip<br> export20220129-184615.zip<br> b4import20220129-194141.zip</p></div><p>Une fois certain de restaurer la bonne sauvegarde, <code>D&#39;accord</code></p><div class="admonition xdripitem"><p class="admonition-title">Confirm Import</p><p> Do you really want to import<br>  &#39;export20220129-184615.zip&#39;?<br>  This may negatively affect the data integrity of your system!</p><p> ANNULER    <span style="background-color:white;color:black;"> D&#39;ACCORD </span></p></div><p>xDrip confirmera que la base de données a bien été restaurée.</p><div class="admonition xdripitem"><p class="admonition-title">Import Result</p><p> Successfully imported database</p></div><p>Si vous avez restauré la mauvaise base de données, refaites simplement les mêmes étapes et sélectionnez la dernière version <code>b4import</code> pour revenir en arrière.</p><div class="info custom-block"><p class="custom-block-title">Android 11 et versions ultérieures</p><p>Un problème avec les versions récentes d&#39;Android vous oblige à restaurer la base de données plusieurs fois (3 à 4) avant de voir l&#39;intégralité de son contenu.</p></div><br><h2 id="cloud-backup" tabindex="-1">Sauvegarde dans le cloud <a class="header-anchor" href="#cloud-backup" aria-label="Permalink to &quot;Sauvegarde dans le cloud {#cloud-backup}&quot;">​</a></h2><p>La sauvegarde dans le cloud vous permet d&#39;enregistrer dans votre Google Drive un fichier compressé contenant à la fois la base de données et les paramètres.<br> Vous devez être connecté à votre compte Google pour utiliser cette fonction.</p><p>Sélectionnez Sauvegarde dans le Cloud.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Fonctionnalités Import / Export ►<br>  Sauvegarde dans le Cloud</p></div><div class="admonition xdripitem"><p class="admonition-title">Sauvegarde dans le Cloud</p><p>  Vous pouvez utiliser Google Drive pour la sauvegarde<br>        Prêt</p></div><p>Pour utiliser cette fonction, vous devez d&#39;abord sélectionner un emplacement de sauvegarde.</p><h3 id="select-backup-location" tabindex="-1">Sélectionner l&#39;emplacement de la sauvegarde <a class="header-anchor" href="#select-backup-location" aria-label="Permalink to &quot;Sélectionner l&#39;emplacement de la sauvegarde {#select-backup-location}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Sélectionner l&#39;emplacement de la sauvegarde </span></p></div><div class="admonition xdripitem"><p class="admonition-title">Choisir le fichier de sauvegarde</p><p>  Sélectionner Automatique pour que xDrip gère les fichiers dans Google Drive ou sélectionner un autre fichier spécifique à utiliser si vous devez restaurer à partir d&#39;ailleurs.</p><p>       <span style="background-color:white;color:black;"> SAUVEGARDE GÉRÉE AUTOMATIQUEMENT </span></p><p>        <span style="background-color:white;color:black;"> UTILISER UN FICHIER ALTERNATIF </span></p></div><ul><li>Utiliser un fichier alternatif vous permet de choisir un autre dossier et un autre fichier de sauvegarde lors d&#39;une <strong>restauration</strong>.</li><li>Pour votre <strong>première sauvegarde</strong>, ou pour récupérer après <strong>une réinstallation de xDrip</strong> sur le même téléphone, sélectionnez Sauvegarde gérée automatiquement.</li></ul><p>Vous devez autoriser xDrip à accéder à votre compte Google. xDrip se contentera d&#39;enregistrer et de récupérer le fichier de sauvegarde dans votre Google Drive. <strong>Rien d&#39;autre.</strong></p><img src="'+s+'" style="zoom:75%;"><p>Une fois cela fait, xDrip confirmera l&#39;accès :</p><img src="'+o+'" style="zoom:75%;"><p>xDrip créera un nouveau dossier nommé xDrip-Backups à la racine de votre Google Drive.</p><img src="'+t+'" style="zoom:75%;"><h3 id="do-backup-now" tabindex="-1">Sauvegarder maintenant <a class="header-anchor" href="#do-backup-now" aria-label="Permalink to &quot;Sauvegarder maintenant {#do-backup-now}&quot;">​</a></h3><p>Une fois l&#39;emplacement de sauvegarde sélectionné, vous pouvez lancer une sauvegarde. Le fichier de sauvegarde est créé sur votre appareil puis envoyé vers votre Google Drive.</p><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Sauvegarder Maintenant </span></p></div><img src="'+i+'" style="zoom:75%;"><p>Vous pouvez vérifier l&#39;état de la sauvegarde dans le cloud en haut de l&#39;écran.</p><img src="'+n+'" style="zoom:75%;"><p>Vous pouvez faire exécuter automatiquement la sauvegarde dans le cloud chaque jour.<br> Ne l&#39;activez pas si votre forfait de données mobiles est limité.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+d+'" style="zoom:75%;"> Sauvegarde journalière automatique</p></div><h3 id="restore-from-backup" tabindex="-1">Restaurer depuis la sauvegarde <a class="header-anchor" href="#restore-from-backup" aria-label="Permalink to &quot;Restaurer depuis la sauvegarde {#restore-from-backup}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Restaurer depuis la sauvegarde </span></p></div><div class="warning custom-block"><p class="custom-block-title">Perte de données</p><p>Restaurer une base de données supprime toutes les données actuelles.<br> Restaurez une base de données avec <strong>la même version de xDrip que celle utilisée pour l&#39;exporter</strong>.<br> Veillez à sauvegarder la base de données actuelle avant d&#39;en restaurer une.</p></div><div class="admonition xdripitem"><p class="admonition-title">Êtes-vous vraiment sûr ?</p><p> Restaurer une sauvegarde effacera vos paramètres et données actuelles de la sauvegarde.</p><p> Êtes-vous absolument sûr de vouloir le faire ?</p><p> NON    <span style="background-color:white;color:black;"> OUI </span></p></div><p>La restauration copie localement la base de données du cloud et remplace la base de données actuelle.</p><p>Une fois l&#39;opération terminée, xDrip redémarre.</p><br><h2 id="new-phone-migration" tabindex="-1">Migration vers un nouveau téléphone <a class="header-anchor" href="#new-phone-migration" aria-label="Permalink to &quot;Migration vers un nouveau téléphone {#new-phone-migration}&quot;">​</a></h2><p>Effectuez les opérations suivantes :</p><p>Sur l&#39;ancien téléphone :</p><ol><li><p><a href="#backup-the-database">Sauvegardez la base de données localement</a> ou dans votre <a href="#do-backup-now">Google Drive</a>.</p><ul><li>Si vous n&#39;utilisez pas la sauvegarde Google dans le cloud, envoyez-vous la sauvegarde de la base de données ou copiez-la sur un ordinateur.</li></ul></li><li><p>Si cet ancien téléphone est connecté à un capteur ou à un transmetteur, veillez à <a href="./../install/datasource.html#changing-data-source">désactiver la collecte</a> pour qu&#39;il n&#39;interfère pas lorsque vous commencerez à utiliser votre nouveau téléphone.</p></li><li><p>Si cet ancien téléphone était principal pour des abonnés xDrip Sync, <a href="./../use/sync.html#be-master-for-followers">retirez-lui le rôle de principal</a>.</p></li></ol><p>Sur le nouveau téléphone :</p><ol><li><p><a href="./../install/download.html#which-one-to-install">Installez</a> la <a href="./../install/install.html#verify-which-version-is-installed">même version</a> de xDrip que celle de l&#39;ancien téléphone.</p><ul><li>Si vous n&#39;avez pas utilisé la sauvegarde Google dans le cloud :<br><a href="#backup-the-database">Sauvegardez la base de données</a> (uniquement pour créer les bons dossiers).<br> Copiez dans le bon dossier le fichier de base de données que vous vous êtes envoyé par e-mail, ou depuis un ordinateur.</li></ul></li><li><p><a href="#restore-a-database">Restaurez la base de données depuis la sauvegarde locale</a> ou depuis votre <a href="#restore-from-backup">Google Drive</a>.</p></li><li><p>Si le nouveau téléphone doit être connecté à un capteur ou à un transmetteur, <a href="./../install/datasource.html#sensor-selection">connectez-le maintenant</a>. (Votre source de données sera correcte, mais vous devrez rétablir la connexion.)</p></li></ol><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',89)])])}const _=u(v,[["render",b]]);export{R as __pageData,_ as default};
